def workbook_html(text):
    out='';code=False;buffer=[]
    for line in text.splitlines():
        if line.startswith('```'):
            if code:out+='<pre><code>'+e('\n'.join(buffer))+'</code></pre>';buffer=[]
            code=not code
        elif code:buffer.append(line)
        elif line.strip():out+='<p>'+e(line)+'</p>'
    return out

