def depth_guide(cid):
    d = CHAPTER_DEPTH[cid]
    tiers = ''.join(('<section class="depth-tier"><span class="eyebrow">' + e(label) + '</span><h4>' + e(heading) + '</h4><p>' + e(d[key]) + '</p></section>' for label, heading, key in [('01 / BASIC', 'Understand the model', 'basic'), ('02 / INTERMEDIATE', 'Connect the moving parts', 'intermediate'), ('03 / ADVANCED', 'Reason about boundaries and failure', 'advanced')]))
    return '<article class="concept-depth" id="depth-' + cid + '" data-chapter="' + cid + '"><header><span class="eyebrow">CONCEPT STUDY / BASIC TO ADVANCED</span><h3>Understand the chapter before using its tools.</h3><p>Read the three levels, explain the example, then answer the question before opening the answer.</p></header><div class="depth-grid">' + tiers + '</div><div class="depth-example"><h4>Worked example</h4><p>' + e(d['example']) + '</p><h4>Common mistake</h4><p>' + e(d['mistake']) + '</p></div><div class="depth-check"><h4>Check your understanding</h4><p>' + e(d['question']) + '</p><details><summary>Reveal the answer and reasoning</summary><div class="detailsbody"><p>' + e(d['answer']) + '</p></div></details></div></article>'




def network_layer_guides(cid):
    if cid!='netfund':return ''
    out='<article class="layer-guide layer-intro" id="layers-overview" data-chapter="netfund"><span class="eyebrow">NETWORK LAYERS / BASIC TO ADVANCED</span><h3>Use layers to explain responsibilities.</h3><p>A network model separates responsibilities so you can describe a packet journey and localize a fault. OSI has seven layers. TCP/IP is commonly described with four groups; the five-layer teaching model splits its link group into data-link and physical layers.</p><p>The grouping is approximate. TCP/IP applications commonly implement representation and dialog functions themselves. TLS, QUIC, tunnels and devices that inspect several layers show why a rigid one-to-one assignment can mislead.</p><div class="layer-table"><table><caption>OSI to TCP/IP conceptual mapping</caption><thead><tr><th scope="col">OSI layer</th><th scope="col">TCP/IP group</th><th scope="col">Typical data unit</th></tr></thead><tbody>'
    for r in NETWORK_LAYERS:out+='<tr><th scope="row">'+r['number']+' / '+e(r['name'])+'</th><td>'+e(r['tcpip'])+'</td><td>'+e(r['unit'])+'</td></tr>'
    out+='</tbody></table></div><h4>Names, addresses and ports answer different questions</h4><p>A DNS name identifies a named service or resource in a naming system. An IP address participates in network routing. A MAC address supports local-link delivery. A TCP/UDP port identifies a transport endpoint. None alone proves who a user is or whether an operation is allowed.</p><h4>What a router changes</h4><p>At an ordinary routed hop, the incoming link envelope is removed and a new one is created for the outgoing link. IP forwarding fields such as TTL or Hop Limit change. Without NAT, a typical end-to-end IP source/destination pair remains the same; configured translation can change addresses or ports.</p><h4>Devices can span layers</h4><p>A network card implements physical and link functions. A multilayer switch can also route. A firewall or proxy can inspect several layers. Avoid treating the product name as an exclusive layer number.</p><p><a href="https://www.itu.int/rec/T-REC-X.200-199407-I/en">ITU-T OSI reference model</a> · <a href="https://www.rfc-editor.org/rfc/rfc1122.html">Internet host communication layers</a></p></article><div class="layer-grid">'
    for r in NETWORK_LAYERS:
        out+='<article class="layer-guide" id="osi-layer-'+r['number']+'" data-chapter="netfund"><span class="eyebrow">OSI LAYER '+r['number']+'</span><h3>'+e(r['name'])+'</h3>'
        for label,key in [('Basic: responsibility','basic'),('Intermediate: mechanisms','intermediate'),('Advanced: boundaries','advanced'),('Example and diagnosis','example')]:out+='<h4>'+label+'</h4><p>'+e(r[key])+'</p>'
        out+='<h4>Check your understanding</h4><p>'+e(r['question'])+'</p><details><summary>Reveal answer</summary><div class="detailsbody"><p>'+e(r['answer'])+'</p></div></details></article>'
    out+='</div><article class="layer-guide" id="layer-practice" data-chapter="netfund"><h3>Practice: diagnose from the bottom up</h3><ol><li>Physical/link: inspect the intended interface and whether the local connection exists.</li><li>Network: inspect address, prefix and route to the intended destination.</li><li>Transport: confirm the service listens on the intended address and port.</li><li>Application and representation: inspect protocol status, expected content, identity and parsing.</li></ol><p>Use Lab 03 for a localhost HTTP exchange. Loopback does not traverse a physical cable; it cannot test a network card, switch or router. Use the conceptual journey to explain the layers the local test does and does not exercise.</p><details><summary>Exercise answer: curl works locally, another computer fails</summary><div class="detailsbody"><p>Local success supports a working local listener and application exchange. It does not establish a remote path. Check the bind address, remote route and firewall policy. A listener bound only to loopback is not normally reachable from another computer.</p></div></details><details><summary>Exercise answer: TCP connects, but the report is missing</summary><div class="detailsbody"><p>Transport was established. Examine the HTTP response, redirects, authorization state and returned content. Replacing a cable is not justified by that evidence alone.</p></div></details></article>'
    return out

def protocol_guides(cid):
    if cid!='netservices':return ''
    out='<div class="callout"><strong>Network protocols: basic to advanced</strong><p>Read link and IP protocols first, then transport, naming/configuration, secure applications and routing. Each guide distinguishes protocol purpose from default port conventions. Layer models are teaching aids; a port number never proves service identity.</p><p>Practical companions: the local HTTP exercise in Lab 03, packet exercises in Labs 09-10, and the fictional subnet calculations in Lab 02. Reading this page sends no requests to your network.</p></div><div class="protocol-grid">'
    for p in PROTOCOL_CONCEPTS:
        out+='<article class="protocol-guide" id="protocol-'+p['id']+'" data-chapter="'+cid+'"><span class="eyebrow">PROTOCOL / '+e(p['layer'])+'</span><h3>'+e(p['name'])+'</h3><p class="protocol-port"><strong>Transport / port:</strong> '+e(p['ports'])+'</p>'
        for label,key in [('Basic: purpose','basic'),('Intermediate: operation','intermediate'),('Advanced: limits and design','advanced'),('Example and troubleshooting','example')]:out+='<h4>'+e(label)+'</h4><p>'+e(p[key])+'</p>'
        out+='<a href="'+e(p['source'])+'">Official specification or documentation</a></article>'
    return out+'</div>'

def anatomy_figures(cid):
    out=''
    for m in ANATOMY_MODELS:
        if m['chapter']!=cid:continue
        key=m['key']
        out+='<article class="anatomy-study" data-anatomy="'+key+'" data-chapter="'+cid+'" id="anatomy-'+key+'"><span class="eyebrow">ILLUSTRATED LESSON / SELECT A COMPONENT</span><h3>'+e(m['title'])+'</h3><p>'+e(m['note'])+'</p><div class="an-image">'+ANATOMY_SVGS[key]+'</div><p class="an-instructions">Select a numbered part in the image or a named button below. On a narrow screen, scroll the illustration sideways. Keyboard: Tab to a part, then Enter or Space.</p><div class="an-choices">'
        for i,p in enumerate(m['parts']):out+='<button class="btn an-choice" type="button" aria-pressed="false" aria-controls="an-info-'+key+'-'+str(i)+'">'+('' if key=='osi-tcpip-layers' else str(i+1)+'. ')+e(p['name'])+'</button>'
        out+='</div><div class="an-toolbar" hidden><button class="btn" type="button" data-an-action="play" aria-pressed="false">Play guided tour</button><button class="btn" type="button" data-an-action="next">Next component</button><button class="btn" type="button" data-an-action="reset">Reset</button><span class="an-status" role="status" aria-live="polite"></span></div>'
        for i,p in enumerate(m['parts']):
            out+='<section class="an-info" id="an-info-'+key+'-'+str(i)+'"><h4>'+e(p['name'])+'</h4><p><strong>What it does:</strong> '+e(p['purpose'])+'</p><p><strong>How it connects:</strong> '+e(p['connect'])+'</p><p><strong>Understand the limits:</strong> '+e(p['advanced'])+'</p></section>'
        if key in ('motherboard','rear-ports'):out+='<p class="an-reference">For a real board, follow its exact manufacturer manual. <a href="https://dlcdnets.asus.com/pub/ASUS/mb/LGA1700/PRIME_B760M-AJ_D4/E21187_PRIME_B760M-AJ_D4_UM_WEB.pdf">Example manufacturer layout and connector manual</a>. Original schematic artwork; not a reproduction of that model.</p>'
        out+='</article>'
    return out

def chapter_visual(cid):
    v = CHAPTER_VISUALS[cid]
    labels = [step['label'] for step in v['steps']]
    svg = '<svg class="cv-svg" viewBox="0 0 780 130" role="img" aria-labelledby="cv-title-' + cid + '"><title id="cv-title-' + cid + '">' + e(v['title']) + ': ' + e(' then '.join(labels)) + '</title>'
    for i, step in enumerate(v['steps']):
        x = 10 + i * 260
        if i < 2:
            svg += f'<path class="cv-link" d="M {x + 235} 62 h 25 m -8 -6 l 8 6 l -8 6" />'
        svg += f'<g class="cv-node" data-frame="{i}"><rect x="{x}" y="12" width="235" height="100" rx="14"/><text x="{x + 18}" y="38" class="cv-number">0{i + 1}</text>'
        words = step['label'].split()
        lines = ['']
        for word in words:
            if len(lines[-1] + ' ' + word) > 23:
                lines.append(word)
            else:
                lines[-1] = (lines[-1] + ' ' + word).strip()
        for j, line in enumerate(lines):
            svg += f'<text x="{x + 18}" y="{65 + j * 21}">' + e(line) + '</text>'
        svg += '</g>'
    svg += '</svg>'
    steps = ''.join(('<li data-frame="' + str(i) + '"><strong>' + e(step['label']) + '</strong><p>' + e(step['body']) + '</p></li>' for i, step in enumerate(v['steps'])))
    return '<figure class="chapter-visual" data-visual="' + cid + '"><figcaption><span class="eyebrow">VISUAL WALKTHROUGH / OFFLINE</span><h3>' + e(v['title']) + '</h3><p>Read the three stages or use Next to follow the explanation. Continue below for basic, intermediate and advanced concepts. This illustration sends no traffic and runs no commands.</p></figcaption>' + svg + '<div class="cv-controls" hidden><button class="btn" type="button" data-cv="play" aria-pressed="false">Play</button><button class="btn" type="button" data-cv="next">Next step</button><button class="btn" type="button" data-cv="reset">Reset</button><span class="cv-status" role="status" aria-live="polite"></span></div><ol class="cv-steps">' + steps + '</ol></figure>'
