SOURCES += [('Feroxbuster official repository', 'https://github.com/epi052/feroxbuster', 'Project and installation.'), ('Feroxbuster flags', 'https://www.kali.org/tools/feroxbuster/', 'Current packaged command reference.'), ('Arjun flags', 'https://www.kali.org/tools/arjun/', 'Parameter discovery controls.'), ('Param Miner', 'https://github.com/PortSwigger/param-miner', 'Extension behavior.'), ('Autorize', 'https://github.com/PortSwigger/autorize', 'Authorization comparison workflows.'), ('JWT Editor', 'https://github.com/PortSwigger/jwt-editor', 'Token editor and verification.'), ('Dalfox', 'https://github.com/hahwul/dalfox', 'XSS assessment tool.'), ('mitmproxy getting started', 'https://docs.mitmproxy.org/stable/overview-getting-started/', 'Explicit proxy use.'), ('testssl.sh manual', 'https://github.com/testssl/testssl.sh/blob/3.2/doc/testssl.1.md', 'TLS testing options.'), ('ZAP Automation Framework', 'https://www.zaproxy.org/docs/automate/automation-framework/', 'Ordered automation jobs.'), ('Schemathesis', 'https://schemathesis.readthedocs.io/en/stable/', 'API schema testing.'), ('Nuclei HTTP templates', 'https://docs.projectdiscovery.io/templates/protocols/http/basic-http', 'Request template structure.'), ('Semgrep rule syntax', 'https://docs.semgrep.dev/writing-rules/rule-syntax', 'Local rule structure.'), ('Semgrep running rules', 'https://docs.semgrep.dev/running-rules', 'Local scans.'), ('Gitleaks', 'https://github.com/gitleaks/gitleaks', 'Secret scanning and redaction.'), ('pip-audit', 'https://github.com/pypa/pip-audit', 'Python dependency advisories.'), ('npm audit', 'https://docs.npmjs.com/cli/v11/commands/npm-audit/', 'Registry auditing and exit behavior.')]
LABS = [('01', 'Your first terminal session', 'Understand paths, files and output.', [('Open Kali Terminal', 'Run examples inside Kali, not Windows PowerShell. The $ prompt in tutorials is not part of the command.', ''), ('Prepare a workspace', 'This creates a directory and replaces notes.txt if it exists.', 'mkdir -p "$HOME/kali-lab"\ncd "$HOME/kali-lab"\nprintf "My first Kali lab\\n" > notes.txt'), ('Read and inspect', 'Compare the content with the permissions and size.', 'pwd\nls -lah\ncat notes.txt\nstat notes.txt'), ('Look up flags', 'Press q to leave the manual.', 'man ls')]), ('02', 'Inspect your own web service', 'Observe a port, an HTTP response and a saved scan.', [('Create a tiny website', 'This creates or replaces the training page.', 'mkdir -p "$HOME/kali-lab/www"\nprintf "<h1>Kali local lab</h1>\\n" > "$HOME/kali-lab/www/index.html"'), ('Start a server in Terminal A', 'Keep this terminal open. Binding to 127.0.0.1 restricts access to this Kali VM.', 'python3 -m http.server 8000 --bind 127.0.0.1 --directory "$HOME/kali-lab/www"'), ('Inspect from Terminal B', 'Expect HTTP 200 and an open 8000/tcp port. Install nmap from the Packages chapter if absent.', 'curl -i http://127.0.0.1:8000/\nnmap -sT -p 8000 --reason 127.0.0.1\nnmap -sV -p 8000 -oN "$HOME/kali-lab/web-scan.txt" 127.0.0.1'), ('Compare after stopping', 'Press Ctrl+C in Terminal A. Repeat the check in Terminal B; the port should normally become closed.', 'nmap -sT -p 8000 127.0.0.1')]), ('03', 'Watch your own packets', 'Connect an HTTP request to a packet trace.', [('Restart the local web lab', 'Use the server command from Lab 07 in Terminal A.', ''), ('Capture in Terminal B', 'Generate traffic in Terminal C next. Capture stops at 20 packets; Ctrl+C stops it earlier.', 'sudo tcpdump -i lo -c 20 -w "$HOME/kali-lab/lab.pcap" "tcp port 8000"'), ('Generate traffic in Terminal C', 'Send two local requests.', 'curl http://127.0.0.1:8000/\ncurl http://127.0.0.1:8000/'), ('Inspect the saved capture', 'After stopping capture, change ownership of only this lab file and open Wireshark as your normal user. Filter with http or tcp.port == 8000. HTTPS would encrypt application contents.', 'sudo chown "$(id -u):$(id -g)" "$HOME/kali-lab/lab.pcap"\ncapinfos "$HOME/kali-lab/lab.pcap"\nwireshark "$HOME/kali-lab/lab.pcap"')]), ('04', 'Prove that a file changed', 'Compare file bytes with a checksum.', [('Record a baseline', 'This replaces the dedicated exercise file and manifest.', 'cd "$HOME/kali-lab"\nprintf "original\\n" > evidence.txt\nsha256sum evidence.txt > evidence.sha256\nsha256sum -c evidence.sha256'), ('Make a controlled change', '>> appends. The check should report FAILED because the file differs.', 'printf "added line\\n" >> evidence.txt\nsha256sum -c evidence.sha256'), ('Interpret the result', 'A different digest proves bytes differ, but not who changed them or whether the change is malicious.', '')]), ('05', 'Write an inventory script', 'Build a readable local workflow.', [('Save the script', 'The quoted heredoc marker prevents expansion while writing. This replaces check.sh in your lab directory.', 'cat > "$HOME/kali-lab/check.sh" <<\'EOF\'\n#!/usr/bin/env bash\nset -e\nprintf "=== CPU ===\\n"\nlscpu\nprintf "=== MEMORY ===\\n"\nfree -h\nprintf "=== STORAGE ===\\n"\ndf -h\nEOF'), ('Check and run', 'First check syntax, then run and record output. Review system details before sharing reports.', 'bash -n "$HOME/kali-lab/check.sh"\nbash "$HOME/kali-lab/check.sh" | tee "$HOME/kali-lab/system-report.txt"'), ('Understand pipeline status', 'A pipeline normally returns the status of its final command. In Bash, set -o pipefail also considers earlier failures. set -e has exceptions and is not complete error handling.', '')])]
LABS.append(('06', 'Metasploit: localhost to recorded evidence', 'Use a scanner against your own web server, then inspect database records and a reviewed resource script.', [('Kali Terminal A: start the web lab', 'Keep this terminal running. The page and private report directory are dedicated exercise files.', 'mkdir -p "$HOME/kali-lab/www"\nmkdir -p /tmp/kali-book-lab\nchmod 700 /tmp/kali-book-lab\nprintf "<title>Kali Metasploit Lab</title><h1>Local lab</h1>\\n" > "$HOME/kali-lab/www/index.html"\npython3 -m http.server 8000 --bind 127.0.0.1 --directory "$HOME/kali-lab/www"'), ('Kali Terminal B: create evidence and open Metasploit', 'Install nmap or metasploit-framework first if missing. The report path below is inside Kali, not host Windows storage.', 'nmap -sT -sV -p 8000 -oX /tmp/kali-book-lab/scan.xml 127.0.0.1\nmsfconsole -q'), ('Inside msfconsole: inspect and run one module', 'Execute one line at a time. Review show options before run. This HTTP scanner reports a fingerprint; it does not create a session or prove a vulnerability.', 'use auxiliary/scanner/http/http_version\ninfo\nset RHOSTS 127.0.0.1\nset RPORT 8000\nset SSL false\nset THREADS 1\nshow options\nrun\nback'), ('Inside msfconsole: check database availability', 'If disconnected, use a separate Kali terminal to check sudo msfdb status. On an uninitialized installation, sudo msfdb init creates local database resources. Restart msfconsole and confirm db_status before proceeding. Do not reinitialize a working database.', 'db_status'), ('Inside msfconsole: record the scan', 'Continue only with a connected database. A workspace organizes records; it is not a network access boundary.', 'workspace -a kali-book-lab\nworkspace kali-book-lab\ndb_import /tmp/kali-book-lab/scan.xml\nhosts\nservices -p 8000'), ('Kali Terminal C: prepare a read-only resource file', 'This file contains console commands. Review it with cat. Never execute an unreviewed resource file.', "printf 'version\\ndb_status\\nworkspace\\nhosts\\nservices\\n' > /tmp/kali-book-lab/inspect.rc\ncat /tmp/kali-book-lab/inspect.rc"), ('Inside msfconsole: replay and document', 'Spool records console output. This resource only reads status and records. The temporary folder may be cleared on reboot; copy wanted reports into your lab folder afterward.', 'spool /tmp/kali-book-lab/console.txt\nresource /tmp/kali-book-lab/inspect.rc\nspool off\njobs -l\nsessions -l'), ('Finish the lab', 'No sessions are expected from the HTTP scanner. Review jobs before exit. Stop the web server with Ctrl+C in Terminal A. Keep any reports you need before the temporary directory is cleared.', 'exit')]))
LABS.append(('07', 'Nmap: compare a service before and after', 'Create two comparable XML reports and explain one intentional change.', [('Kali Terminal A: prepare the exercise', 'Use a fresh port 8765 so this exercise does not depend on the earlier HTTP server. If ss shows a listener, choose another unused port consistently. Create your private report directory.', 'mkdir -p "$HOME/kali-lab/www"\nss -ltn sport = :8765'), ('Kali Terminal B: record the baseline', 'Run before starting the server. The port should be closed. This replaces before.xml if it exists.', 'nmap -sT -p 8765 -oX "$HOME/kali-lab/before.xml" 127.0.0.1'), ('Kali Terminal A: start one local service', 'Keep the process running while recording the next scan.', 'python3 -m http.server 8765 --bind 127.0.0.1 --directory "$HOME/kali-lab/www"'), ('Kali Terminal B: record the same scan again', 'Keep the target and scan options identical so the intentional service change is easy to interpret.', 'nmap -sT -p 8765 -oX "$HOME/kali-lab/after.xml" 127.0.0.1'), ('Compare and interpret', 'Expect port 8765 to change from closed to open. Ndiff exit code 1 means differences were found, not failure. If ndiff is absent, Kali provides the ndiff package; install it with sudo apt install ndiff.', 'ndiff "$HOME/kali-lab/before.xml" "$HOME/kali-lab/after.xml"\nndiff --xml "$HOME/kali-lab/before.xml" "$HOME/kali-lab/after.xml" > "$HOME/kali-lab/changes.xml"'), ('Finish and document', 'Stop the server with Ctrl+C in Terminal A. Record scan times and the service you started. Unexpected differences can result from filtering, packet loss or changed scan options; validate them before claiming a configuration change.', '')]))
LABS.append(('08', 'Shodan: understand an export offline', 'Use fictional records to distinguish addresses, services and observation timestamps. No account, API key or network access is required for the Python steps.', [('Create fictional observations in Kali Terminal', 'This creates or replaces only shodan-sample.json.gz in your practice folder. The documentation addresses and banners are invented and are not Shodan search results.', 'mkdir -p "$HOME/kali-lab"\npython3 - <<\'PY\'\nimport gzip, json\nfrom pathlib import Path\nrows = [\n    {"ip_str":"198.51.100.10","port":443,"transport":"tcp","timestamp":"2026-09-18T10:00:00.000000","data":"FICTIONAL HTTPS LAB RECORD"},\n    {"ip_str":"198.51.100.10","port":22,"transport":"tcp","timestamp":"2026-09-18T10:01:00.000000","data":"FICTIONAL SSH LAB RECORD"},\n    {"ip_str":"198.51.100.20","port":443,"transport":"tcp","timestamp":"2026-09-18T10:02:00.000000","data":"FICTIONAL HTTPS LAB RECORD"}\n]\npath = Path.home() / \'kali-lab\' / \'shodan-sample.json.gz\'\nwith gzip.open(path, \'wt\', encoding=\'utf-8\') as f:\n    for row in rows:\n        f.write(json.dumps(row) + \'\\n\')\nprint(\'Fictional sample saved:\', path)\nPY'), ('Inspect the sample with standard Python', 'Expect three service records and two unique addresses. One address has two ports. The sample uses JSON Lines inside gzip, not a single JSON array.', "python3 - <<'PY'\nimport gzip, json\nfrom pathlib import Path\npath = Path.home() / 'kali-lab' / 'shodan-sample.json.gz'\nwith gzip.open(path, 'rt', encoding='utf-8') as f:\n    rows = [json.loads(line) for line in f if line.strip()]\nprint('Service records:', len(rows))\nprint('Unique addresses:', len({r['ip_str'] for r in rows}))\nfor row in rows:\n    print(row['ip_str'], row['transport'], row['port'], row['timestamp'])\nPY"), ('Optional: inspect with the installed Shodan CLI', 'If you already installed the client in the chapter environment, activate it and parse locally. This step does not require authentication; installing the client itself requires internet.', 'source "$HOME/kali-lab/shodan-venv/bin/activate"\nshodan parse --fields ip_str,port,timestamp "$HOME/kali-lab/shodan-sample.json.gz"'), ('Interpret the evidence', 'A row represents a service observation. Multiple rows do not necessarily mean multiple devices. The timestamp describes the fictional observation time, not when you opened the file. None of these records demonstrates a vulnerability.', ''), ('Plan a real inventory workflow', 'Before any online exercise, identify your owned public ranges, check account access and credit limits, count a narrowly scoped query, then review a small sample. Do not replace documentation addresses with arbitrary discovered systems.', '')]))
LABS += [('09', 'Map a local web application', 'Build a static local site, learn HTTP baselines and compare two discovery tools.', [('Kali Terminal: create the site', 'These commands replace the named practice files only.', 'mkdir -p "$HOME/kali-lab/web-practice/site/help"\nprintf \'<title>Web practice</title><a href="/help/">Help</a>\\n\' > "$HOME/kali-lab/web-practice/site/index.html"\nprintf \'<h1>Public help</h1>\\n\' > "$HOME/kali-lab/web-practice/site/help/index.html"\nprintf \'User-agent: *\\nDisallow: /training-only/\\n\' > "$HOME/kali-lab/web-practice/site/robots.txt"\nprintf \'help\\nrobots.txt\\nmissing-page\\n\' > "$HOME/kali-lab/web-practice/words.txt"'), ('Terminal A: start the service', 'Leave this terminal open; the server binds only to Kali loopback.', 'python3 -m http.server 8877 --bind 127.0.0.1 --directory "$HOME/kali-lab/web-practice/site"'), ('Terminal B: compare known and missing routes', 'Expect 200 for help/ and 404 for missing-page.', 'curl -i http://127.0.0.1:8877/help/\ncurl -i http://127.0.0.1:8877/missing-page'), ('Terminal B: try Gobuster', 'Requires Gobuster to be installed. Compare discoveries with the files you created.', 'gobuster dir -u http://127.0.0.1:8877/ -w "$HOME/kali-lab/web-practice/words.txt" -t 1 --delay 500ms'), ('Terminal B: compare ffuf', 'Requires ffuf. Display all status codes first; explain the missing-path result.', 'ffuf -u http://127.0.0.1:8877/FUZZ -w "$HOME/kali-lab/web-practice/words.txt" -t 1 -rate 2 -mc all'), ('Stop or continue', 'Keep the server for Lab 16, or press Ctrl+C in Terminal A. This exercise demonstrates discovery, not an exploitable vulnerability.', '')]), ('10', 'Inspect and modify one request in Burp', 'Continue with the local service from Lab 13. No paid Scanner feature is needed.', [('Kali Terminal: open Burp', 'Choose a temporary project.', 'burpsuite'), ('Burp GUI: open browser', 'Use Proxy > Open browser, visit the local URL and leave Intercept off initially.', ''), ('Burp GUI: inspect history', 'Locate the request to 127.0.0.1:8877 and add the exact origin to scope. Inspect its response.', ''), ('Burp GUI: compare in Repeater', 'Send the request to Repeater. Send /, then change only the path to /missing-page and send again. Expect 200 and 404.', ''), ('Write the explanation', 'Record what changed, why the response changed, and why this does not prove a vulnerability. Stop the local server with Ctrl+C when finished.', '')]), ('11', 'Plan an access-control assessment', 'A worksheet for a separate training app with two test users; the static website cannot demonstrate authentication.', [('Create a role/object matrix', 'Use two consenting lab accounts and synthetic objects. Define expected allow and deny decisions.', 'Role | Action | Own object | Other test user object | Expected decision\nGuest | View private profile | N/A | Deny | Login required\nUser A | View profile | Allow | Deny | Object ownership enforced\nAdmin | Support lookup | Policy | Policy | Audited access'), ('Record a permitted baseline', 'Capture one harmless request for User A own object. Verify the session identity and record expected content.', ''), ('Change one condition', 'Repeat with User B session or the other synthetic object identifier, changing one variable at a time. Confirm response content and side effects.', ''), ('Document and retest', 'If observed access contradicts policy, save redacted evidence. After a fix, retest the denied case and a legitimate permitted case.', 'Title and affected route\nScope, time, application build and test role\nExpected behavior and observed behavior\nMinimal reproduction using synthetic data\nRedacted request and response evidence\nImpact, root cause and remediation\nRetest steps, result and remaining limitations')])]
LABS += [('12', 'Observe a TCP conversation', 'Use only Kali loopback. Requires Ncat, tcpdump and optionally Wireshark/TShark.', [('Prepare the evidence directory', 'Run inside Kali Terminal.', 'mkdir -p "$HOME/kali-lab/network"'), ('Terminal A: start the listener', 'Leave it waiting. If the port is occupied, stop your earlier lab listener or choose another port consistently.', 'ncat -l 127.0.0.1 9099'), ('Terminal B: begin capture', 'Immediately proceed to Terminal C; capture has a 20-second limit.', 'sudo timeout 20s tcpdump -i lo -nn -s 0 -c 40 -w "$HOME/kali-lab/network/local.pcap" "tcp port 9099"'), ('Terminal C: connect', 'Type hello lab and Enter. Reply from Terminal A, then Ctrl+C in Terminal C. No shell is exposed.', 'ncat 127.0.0.1 9099'), ('Inspect the saved trace', 'Wait until capture stops. Identify the SYN/SYN-ACK/ACK exchange, payload and closure. If empty, repeat with the correct timing.', 'tcpdump -nn -r "$HOME/kali-lab/network/local.pcap"'), ('Optional graphical review', 'Open local.pcap in Wireshark and Follow TCP Stream. Explain why plaintext is visible and why this does not automatically work for encrypted content.', '')]), ('13', 'Measure a bounded local transfer', 'Use iperf3 to distinguish TCP throughput from UDP loss and jitter; these are loopback measurements.', [('Terminal A: server', 'Wait for one client test.', 'iperf3 -s -B 127.0.0.1 -p 5202 -1'), ('Terminal B: TCP test', 'Three seconds with a one-megabit target rate.', 'iperf3 -c 127.0.0.1 -p 5202 -t 3 -b 1M'), ('Terminal A: restart the one-shot server', 'The previous server exits after the test.', 'iperf3 -s -B 127.0.0.1 -p 5202 -1'), ('Terminal B: UDP test', 'Compare sender and receiver results.', 'iperf3 -c 127.0.0.1 -p 5202 -u -b 1M -t 3'), ('Interpret and finish', 'Record duration, rate and transport. Expect little loss on an idle loopback path, but do not assume zero loss is guaranteed. Confirm the one-shot server exited.', '')]), ('14', 'Assess one owned service and its reachability', 'Needs a separate configured lab host, exact address, known listening service and approved source zones.', [('Define the expected policy', 'Replace worksheet entries with your actual lab. Do not create broad firewall changes merely to reproduce a result.', 'Source zone | Destination asset | Protocol/port | Expected | Observed\nLab client | Test server | TCP/443 | Allow | Pending\nLab client | Management interface | TCP/22 | Deny | Pending\nManagement VM | Test server | TCP/22 | Allow | Pending'), ('Inspect the local path', 'Replace the example address before use and record the route.', 'ip route get 192.0.2.10\nip -6 route show'), ('Select one service check', 'Use the SMB, SSH, DNS, SNMP or TLS card that matches the configured service. The credentials, CA file and DNS zone are prerequisites, not supplied by the handbook.', ''), ('Compare the approved vantage points', 'Repeat the same service/port observation from allowed and denied zones. Correlate local listener state and firewall logs. Distinguish deny, closed, timeout and authentication failure.', ''), ('Write a finding only when evidence supports it', 'Record uncertainty and retest after remediation.', 'Record endpoint, protocol, time and scanner observation.\nConfirm asset ownership and service configuration.\nCheck actual package/build and vendor remediation status.\nReproduce the smallest relevant behavior.\nRetest after the configuration or patch change.')])]
LABS += [('15', 'Analyze the same evidence in Python and JavaScript', 'An offline exercise using the supplied scripts and fictional sample.jsonl.', [('Copy the practice files into Kali', 'Copy examples/programming from the book folder into ~/kali-lab/programming using your configured file-transfer method. Verify both runtimes; no third-party package installation is required.', 'cd "$HOME/kali-lab/programming"\npython3 --version\nnode --version'), ('Inspect the input', 'The dataset is fictional. Read it before processing.', 'cat sample.jsonl'), ('Run both analyzers', 'Expect equivalent JSON: records 4; statuses 200:2, 403:1, 404:1. Key ordering is not significant.', 'python3 log_summary.py sample.jsonl\nnode log_summary.mjs sample.jsonl'), ('Try a malformed fixture', 'This creates or replaces bad.jsonl only. Each analyzer should fail clearly and return exit status 1.', 'printf "not-json\\n" > bad.jsonl\npython3 log_summary.py bad.jsonl\nprintf "Python exit: %s\\n" "$?"\nnode log_summary.mjs bad.jsonl\nprintf "Node exit: %s\\n" "$?"'), ('Check the authorization examples', 'The three cases exercise owner access, another user and another tenant. These tests validate the toy functions, not your real application.', 'python3 py_access_tests.py\nnode --test js_access_tests.mjs')]), ('16', 'Compare a localhost HTTP observation', 'Use the supplied header tools with the static site from Lab 13; this is not a vulnerability scan.', [('Terminal A: start the site', 'Create the Lab 13 site first. Keep this process running while you use Terminal B.', 'python3 -m http.server 8877 --bind 127.0.0.1 --directory "$HOME/kali-lab/web-practice/site"'), ('Terminal B: run both languages', 'Run from the folder containing the project files. Both tools use loopback only and do not follow redirects.', 'cd "$HOME/kali-lab/programming"\npython3 local_headers.py 8877\nnode local_headers.mjs 8877'), ('Interpret the output', 'Expect 200 if the lab site exists; otherwise investigate the actual status. A header value of null means absent, not automatically vulnerable. Explain why HEAD observations are not a complete assessment.', ''), ('Observe connection failure', 'Stop Terminal A with Ctrl+C, then repeat one checker. If no other service takes the port, it should report connection failure with a nonzero exit rather than a fabricated report.', 'python3 local_headers.py 8877')])]
LABS.append(('17', 'Run your own web-review programs', 'Use the six supplied source programs and fictional response fixtures.', [('Copy and start', 'Copy examples/web-programs into ~/kali-lab/web-programs in Kali first. Leave the fixture in Terminal A.', 'cd "$HOME/kali-lab/web-programs"\npython3 fixture_server.py --port 8891'), ('Terminal B: review headers and cookies', 'Expect CSP/nosniff/Referrer-Policy on /strong. The cookie report should omit its value.', 'cd "$HOME/kali-lab/web-programs"\npython3 web_review.py headers http://127.0.0.1:8891/strong\nnode web_review.mjs cookies http://127.0.0.1:8891/strong'), ('Inspect CORS and redirects', 'The synthetic Origin is reflected on /cors; /redirect must remain status 302 in the report. These are observations, not confirmed exploits.', 'python3 web_review.py cors http://127.0.0.1:8891/cors\nnode web_review.mjs headers http://127.0.0.1:8891/redirect'), ('Compare evidence offline', 'Explain why the 200 login-page fixture is not equivalent to the 200 owner-page fixture.', 'python3 response_diff.py baseline.json denied.json\nnode response_diff.mjs baseline.json ambiguous.json'), ('Optional browser inventory', 'Open the local root page. Read browser_inventory.js, then run it in Developer Tools Console. Inspect links, form method/destination and field names; do not submit the form.', ''), ('Finish', 'Stop Terminal A with Ctrl+C. Record the result, limitation and next manual validation for each observation.', '')]))
LABS.append(('18', 'Understand and run two custom checks', 'Requires Nuclei and Semgrep installed separately; uses the supplied local templates and teaching source.', [('Copy and inspect', 'Copy examples/advanced-web into ~/kali-lab/advanced-web. Read both rules. Do not execute sample_review.py.', 'cd "$HOME/kali-lab/advanced-web"\ncat local-header.yaml\ncat review-eval.yaml\ncat sample_review.py'), ('Start the synthetic service in Terminal A', 'Use the Chapter 30 fixture files already copied into Kali.', 'python3 "$HOME/kali-lab/web-programs/fixture_server.py" --port 8891'), ('Terminal B: validate and run the Nuclei check', 'The informational match establishes a header observation, not a vulnerability.', 'nuclei -validate -t local-header.yaml\nnuclei -u http://127.0.0.1:8891 -t local-header.yaml -rl 1 -c 1 -ni -duc'), ('Run the source-pattern check', 'Expect one eval finding. Explain what evidence is still needed to decide whether an actual application exposes this behavior.', 'semgrep scan --config review-eval.yaml --metrics=off sample_review.py'), ('Create negative controls', 'Copy the files before editing. In a copy of the Nuclei template, change /strong to /weak and rerun: no nosniff match is expected. In a copy of the teaching source, replace eval(text) with text, then scan that copy: the rule should no longer match.', ''), ('Record limits and stop', 'Save versions and results. A negative control checks the matcher, not complete application security. Ctrl+C stops the fixture server.', '')]))
