SOURCES += [('OWASP authorization', 'https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html', 'Object and field policy.'), ('OWASP OAuth2', 'https://cheatsheetseries.owasp.org/cheatsheets/OAuth2_Cheat_Sheet.html', 'Federated identity controls.'), ('Browser postMessage', 'https://developer.mozilla.org/en-US/docs/Web/API/Window/postMessage', 'Origin and source checks.'), ('OWASP business logic', 'https://cheatsheetseries.owasp.org/cheatsheets/Business_Logic_Security_Cheat_Sheet.html', 'Business invariants.'), ('OWASP threat modeling', 'https://cheatsheetseries.owasp.org/cheatsheets/Threat_Modeling_Cheat_Sheet.html', 'Assets and trust boundaries.'), ('Python unittest', 'https://docs.python.org/3/library/unittest.html', 'Regression testing.'), ('OWASP GraphQL', 'https://cheatsheetseries.owasp.org/cheatsheets/GraphQL_Cheat_Sheet.html', 'Schema and resolver policy.')]
SOURCES += [('Private IPv4 addresses (RFC 1918)', 'https://www.rfc-editor.org/rfc/rfc1918', 'Private address allocation.'), ('IPv6 specification (RFC 8200)', 'https://www.rfc-editor.org/rfc/rfc8200', 'IPv6 packet fundamentals.'), ('Python subnet calculations', 'https://docs.python.org/3/library/ipaddress.html', 'Offline address and prefix arithmetic.')]
TROUBLE = [('command not found', 'Use command -v TOOL and local help. Look up the official Kali package: executable and package names can differ.'), ('Permission denied', 'Check pwd, ls -l and namei -l PATH. Use sudo only when that operation needs it. Avoid chmod 777 as a general fix.'), ('Connection refused', 'Check whether your server is running, its bind address and its port. Use ss -tuln.'), ('Timeout or filtered port', 'A firewall, bad route or offline host can prevent a response. A timeout alone does not prove which one. Check VM network mode.'), ('Empty capture', 'Start capture before generating traffic. Use lo for localhost. Press Ctrl+C if the packet count is not reached.'), ('apt lock / package manager busy', 'Let the existing package process finish. Do not delete lock files while an update is running.'), ('No Wi-Fi interface', 'VirtualBox usually exposes Ethernet even when Windows uses Wi-Fi. Radio-level lab work needs a compatible USB adapter passed to the guest.'), ('No space left', 'Check df -h and du -sh on known folders. Host VDI growth and guest partition capacity are different limits.'), ('An option differs', 'Read man TOOL or installed help. Kali is rolling; your installed version may differ from this reference.'), ('Host drive not visible in Kali', 'A virtual disk file is stored on the host. Linux paths are separate. A deliberate shared folder or file transfer is needed for host/guest access.')]
