        _, num, title, _ = CHAPTER_LOOKUP[cid]
        nav += f'''<button class="navitem" data-view="{cid}" type="button"><span class="num">{num}</span><span>{e(title)}</span><span class="count">{sum((c['chapter'] == cid for c in commands))}</span></button>'''
