    if cid in ADVANCED_WEB_CONCEPTS:
        intro_extra = '<div class="callout"><strong>Use one tool to answer one question</strong><p>Follow the context label: some cards contain GUI workflows or YAML, not terminal commands. Tools need separate installation. Source rules and fixtures are in examples/advanced-web. Start with the existing local labs and inspect generated traffic.</p></div><div class="guidegrid">' + ''.join(('<article class="panel"><h3>' + e(t) + '</h3><p>' + e(d) + '</p></article>' for t, d in ADVANCED_WEB_CONCEPTS[cid])) + '</div>'
